const entrada = $('Webhook').first().json;
const clientes = Array.isArray(entrada.clientes)
  ? entrada.clientes
  : Array.isArray(entrada.body?.clientes)
    ? entrada.body.clientes
    : Array.isArray(entrada)
      ? entrada
      : [];

const csvBruto = $input.first().json.data ?? $input.first().json;
const csvTexto = typeof csvBruto === 'string' ? csvBruto : String(csvBruto);

const linhas = csvTexto.trim().split(/\r?\n/).slice(1);
const investimentos = linhas
  .map((linha) => {
    const [perfil, produto, minimo, rentabilidade] = linha.split(',');
    return {
      perfil: (perfil || '').trim(),
      produto: (produto || '').trim(),
      minimo: Number((minimo || '0').trim()),
      rentabilidade: (rentabilidade || '').trim(),
    };
  })
  .filter((item) => item.perfil && item.produto);

function saldoNumero(saldoTexto) {
  return Number(
    String(saldoTexto)
      .replace(/R\$\s?/g, '')
      .replace(/\./g, '')
      .replace(',', '.')
  );
}

const mensagens = clientes.map((cliente) => {
  const saldo = saldoNumero(cliente.saldo);
  const opcoes = investimentos
    .filter((item) => item.perfil === cliente.perfil)
    .filter((item) => saldo >= item.minimo);

  const escolha = opcoes[0] || investimentos.find((item) => item.perfil === cliente.perfil);

  let mensagem;
  if (!escolha) {
    mensagem = `${cliente.nome}, nao encontrei produto para o perfil ${cliente.perfil}.`;
  } else if (cliente.perfil === 'Conservador') {
    mensagem = `${cliente.nome}, com saldo ${cliente.saldo} e perfil Conservador, a indicacao e ${escolha.produto} (minimo R$ ${escolha.minimo}) com rentabilidade ${escolha.rentabilidade}. Foco em renda fixa e seguranca.`;
  } else if (cliente.perfil === 'Moderado') {
    mensagem = `${cliente.nome}, com saldo ${cliente.saldo} e perfil Moderado, a indicacao e ${escolha.produto} (minimo R$ ${escolha.minimo}) com rentabilidade ${escolha.rentabilidade}. Mix equilibrado entre renda fixa e variavel.`;
  } else {
    mensagem = `${cliente.nome}, com saldo ${cliente.saldo} e perfil Arrojado, a indicacao e ${escolha.produto} (minimo R$ ${escolha.minimo}) com rentabilidade ${escolha.rentabilidade}. Enfase em maior potencial de retorno.`;
  }

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      perfil: cliente.perfil,
      produto: escolha?.produto || null,
      rentabilidade: escolha?.rentabilidade || null,
      mensagem,
    },
  };
});

return mensagens;
